window.PARK_ROADCOND = {"built":"2026-10-27T22:44Z","parks":{"care":{"src":"https://www.nps.gov/care/planyourvisit/conditions.htm","asOf":"10/27/2026","districts":[{"name":"Fruita Historic District","roads":[{"n":"Scenic Drive","c":"2WD","d":"10/27/26"},{"n":"Grand Wash","c":"2WD","d":"10/27/26"},{"n":"Capitol Gorge","c":"Closed","d":"10/27/26"},{"n":"South Draw","c":"Not recommended, extremely rough, likely impassable","d":"10/27/26"},{"n":"Pleasant Creek","c":"Closed","d":"10/27/26"},{"n":"Sulphur Creek","c":"Deep mud, not recommended","d":"10/27/26"},{"n":"Gooseneck","c":"2WD","d":"10/27/26"}]},{"name":"Waterpocket District","roads":[{"n":"Notom-Bullfrog","c":"Unknown, likely impassable","d":"10/27/26"},{"n":"Burr Trail","c":"Unknown, likely impassable","d":"10/27/26"},{"n":"Strike Valley Overlook","c":"Unknown, likely impassable","d":"10/27/26"},{"n":"Halls Creek Overlook","c":"Unknown, likely impassable","d":"10/27/26"},{"n":"Bullfrog Creek Crossing","c":"Unknown, likely impassable","d":"10/27/26"}]},{"name":"Cathedral Valley District","roads":[{"n":"River Ford","c":"Deep mud, likely impassable","d":"10/27/26"},{"n":"Hartnet Road","c":"Unknown","d":"10/27/26"},{"n":"Bentonite Hills Area","c":"Unknown","d":"10/27/26"},{"n":"Cathedral Valley","c":"Deep mud, likely impassable","d":"10/27/26"},{"n":"Baker Ranch","c":"Unknown","d":"10/27/26"},{"n":"Polk Creek","c":"Unknown","d":"10/27/26"},{"n":"Oil Well Bench","c":"Unknown","d":"10/27/26"}]}]},"seki":{"src":"https://www.nps.gov/seki/planyourvisit/road-conditions.htm","asOf":"","districts":[{"name":"Highway 180","roads":[{"n":"Big Stump Entrance Station to Hume Lake Road Grant Grove Area Provides access to Kings Canyon National Park from Fresno and all points to the west. Subject to temporary closure due to snow events.","c":"OPEN","d":""},{"n":"Hume Lake Road to Roads End (access to the Cedar Grove area) Cedar Grove Area Provides access to the Kings River Canyon and Cedar Grove area. This section of the highway closes for the winter. It typically closes in early to mid-November and reopens in late April or early May. Opening and closing dates may change depending on weather and conditions.","c":"OPEN","d":""}]},{"name":"Sequoia National Park Roads","roads":[{"n":"Generals Highway Foothills, Giant Forest, Lodgepole, Grant Grove Areas This is the main highway that connects Sequoia and Kings Canyon National Parks, and provides access to the Giant Forest.","c":"See the Generals Highway Table above.","d":""},{"n":"Middle Fork Road Foothills Area This road leads to Buckeye Flat Campground and is unpaved beyond.","c":"OPEN TO PEDESTRIAN TRAFFIC","d":""},{"n":"Crystal Cave Road Giant Forest Area This road leads to the parking lot for the trail to Crystal Cave. The cave is only open to tours that are reserved in advance. Tours are not available on a walk-up basis. See our Crystal Cave page for more information about tours. Gated each night. This lower half of this road is only open during the day when cave tours are open. Some sections of this road are rough after this road experience extensive damage and impacts from the 2021 KNP Complex Fire and flooding during extreme storms in winter 2022-2023. Drive slow. The road is only open during the day on dates when Crystal Cave tours are offered. This road is always closed at night.","c":"CLOSED FOR THE SEASON The road is expected to reopen in spring 2027.","d":""},{"n":"Crescent Meadow Road and Moro Rock Loop Giant Forest Area In summer , this road is most easily accessed by free shuttles , especially on weekends and federal holidays . The roads are closed to general motor vehicle traffic on summer weekends and holidays when the shuttles are operating. These roads are not cleared of snow in winter or during winter storms. When the roads are closed to vehicles, they are open for winter recreation opportunities such as cross-country skiing and snowshoeing. The roads may reopen if snow melts off the roadway.","c":"OPEN","d":""},{"n":"Wolverton Road Giant Forest Area This road provides access to Wolverton snowplay area and, when it is open, the Sherman Tree Main Trail and Parking Area (see below).","c":"OPEN","d":""},{"n":"Sherman Tree Main Trail and Parking Area Giant Forest Area The main parking lot for walking to the General Sherman Tree. This road and parking area are not cleared of snow in winter or during winter storms. When closed to vehicles, they are open for winter recreation opportunities such as cross-country skiing and snowshoeing. The area will reopen if snow and ice melt off the roadway. When this parking area is closed, parking for the General Sherman Tree is at the Sherman Tree Accessible Parking Area and Accessible Trailhead on Generals Highway.","c":"OPEN This road and parking area are not cleared of snow. When closed to vehicles, they are open for winter recreation opportunities such as cross-country skiing and snowshoeing. The area will reopen if snow and ice melt off the roadway.","d":""},{"n":"Mineral King Road Mineral King Area This road is very narrow and curving and the upper portion is partially unpaved. The road is often less than two lanes wide, and there are no guardrails. RV's and trailers are not recommended (nor permitted in the Mineral King campgrounds). Drive slow. This road closes at the park boundary to general vehicle traffic for the winter season.","c":"OPEN—ACTIVE ALERT BEGINNING SEPTEMBER 8 there will be traffic delays and temporary road closures every day. Details are posted on the Road Construction page . There will be no delays or closures over the Columbus (Indigienous Peoples') Day holiday, from noon on Friday October 9, through 7 am on Tuesday, October 13.","d":""},{"n":"North Fork Road Foothills Area Unpaved. High clearance vehicles strongly recommended.","c":"OPEN—ACTIVE ALERT The last several miles of this road are narrow with many blind curves. The final section near the North Fork Trailhead has deep, wide ruts. Low clearance vehicles are not recommended.","d":""},{"n":"South Fork Road Foothills Area Unpaved. High clearance vehicles recommended. South Fork Road within the boundaries of Sequoia National Park is open to public access after recent road construction to repair damage from past floods and landslides. It is not possible to drive to the old trailhead parking area at end of the road, as shown on maps. South Fork Campground is closed. Trails in the South Fork drainage are not currently passable to stock.","c":"OPEN—ACTIVE ALERT Unpaved. High clearance vehicles recommended.","d":""}]},{"name":"Kings Canyon National Park Roads","roads":[{"n":"Highway 180 Grant Grove, Cedar Grove Areas This highway provides access to Kings Canyon National Park from Fresno, and connects the Grant Grove and Cedar Grove areas of the park.","c":"See the Highway 180 Table above.","d":""},{"n":"Generals Highway Foothills, Giant Forest, Lodgepole, Grant Grove Areas This is the main highway that connects Sequoia and Kings Canyon National Parks, and provides access to the Giant Forest.","c":"See the Generals Highway Table above.","d":""},{"n":"Panoramic Point Road (Panoramic Drive) Grant Grove Area This road leads from Kings Canyon Visitor Center to Panoramic Point. The road is narrow. RVs and trailers are not permitted. This road is not plowed. It closes to vehicles when snow accumulates and is typically closed in the winter and reopens in late May. The road may reopen if snow melts off the roadway before late May. When closed to vehicles in winter, the road is open to non-vehicle winter recreation such as cross-country skiiing, snowshoeing, or walking.","c":"OPEN","d":""},{"n":"Grant Tree Road Grant Grove Area Provides access to trails to General Grant Tree and surrounding sequoia groves.","c":"OPEN","d":""},{"n":"Redwood Mountain Road Grant Grove Area This unpaved road leads from the Generals Highway to Redwood Mountain Trailhead.","c":"OPEN—ACTIVE ALERT The road experienced tread damage and tree hazards following the 2021 KNP Complex wildfire. Temporary repairs are place, but the road is rough in some places. Low clearance vehicles may park at Quail Flat and hikers can walk down the road to access Redwood Canyon Trail.","d":""}]},{"name":"Other Area Roads","roads":[{"n":"Highway 245 Near Grant Grove, west of the parks This highway is often used to drive between Sequoia and Kings Canyon National Parks when Generals Highway is closed in the winter.","c":"OPEN Call 1-800-427-7623 to check conditions, or check the CalTrans website .","d":""},{"n":"Hume Lake Road Sequoia National Forest, northeast of Grant Grove Paved road from Highway 180 to Hume Lake. Usually open year-round.","c":"OPEN Call the Hume Lake Ranger District for the most current road conditions: (559) 338-2251.","d":""},{"n":"Other Sequoia National Forest Roads Paved and unpaved roads near the parks in the Hume Lake Ranger District of Sequoia National Forest","c":"Call the Hume Lake Ranger District for the most current road conditions: (559) 338-2251. Some road information available on the Sequoia National Forest Forest Alerts .","d":""}]}]}}};
